        metricsId +
        '">' +
        '<span class="matching-size-guide__metrics-toggle-label" data-matching-size-guide-metrics-toggle-label>Find your family\'s fit</span>' +
        '<span class="matching-size-guide__metrics-toggle-icon" aria-hidden="true"></span>' +
