  .page-width--product-main .product-media-progress__track::after {
    background: rgba(255, 255, 255, 0.92);
  }

  .page-width--product-main .product__title {
    margin-bottom: 0.6rem !important;
  }

  .page-width--product-main .product__info-container > * + * {
    margin-top: 1.05rem !important;
  }

  .template-product .product__info-container .product__title + [id^='price-'],
  .page-width--product-main .product__info-container .product__title + [id^='price-'] {
    margin-top: 0.35rem !important;
