  /* Mobile PDP option controls: cleaner spacing and lighter borders */
  .page-width--product-main .product__info-container variant-selects,
  .page-width--product-main .product__info-container .product-form__quantity {
    width: 100%;
    max-width: 100%;
    margin: 0 0 1.4rem !important;
    padding: 1.25rem 1.2rem;
    border: 1px solid #ece9e6;
