<script>
window.addEventListener('DOMContentLoaded', () => {
  if (window.matchMedia('(min-width: 750px)').matches) {
    return
  }

  const handleCollapse = (heading) => {
    if (heading.classList.contains('block-collapsed')) {
      heading.classList.remove('block-collapsed')
      heading.setAttribute('aria-expanded', 'true')
      return
    }

    heading.classList.add('block-collapsed')
    heading.setAttribute('aria-expanded', 'false')
  }

  document.querySelectorAll('.footer .footer__blocks-wrapper .footer-block__heading').forEach((heading, index) => {
    const detailsContent = heading.nextElementSibling

    if (!detailsContent) {
      return
    }

    heading.classList.add('block-collapsed')
    heading.setAttribute('role', 'button')
    heading.setAttribute('aria-expanded', 'false')
    heading.setAttribute('tabindex', '0')

    detailsContent.setAttribute('id', `footer-block-index-${index}`)
    heading.setAttribute('aria-controls', `footer-block-index-${index}`)

    heading.addEventListener('click', () => {
      handleCollapse(heading)
    })

    heading.addEventListener('keydown', (event) => {
      // Only handle Enter and Space keys; ignore other key presses
      if (event.key !== 'Enter' && event.key !== ' ') {
        return
      }

      event.preventDefault()
      handleCollapse(heading)
    })
  })
})
</script>

{%- comment -%}
  PDP buy-column canonical block order (CRO Phase 2/3 reference):

    1.  Title
    2.  Price (+ sale anchor)
    3.  Variant picker (with numbered step headings on multi-option SKUs:
        "1. Who is this for? / 2. Choose piece / 3. Choose size")
    4.  Size guide trigger (lives inside the Purchase Confidence panel)
    5.  Buy buttons — primary CTA
        - On matching-set products: matching-set CTA reads as primary
          and the single-piece ATC is demoted to outline-style
          (via :has() in component-product-desktop-ux.css)
    6.  Compressed trust row + three promise rows + collapsed details
        (snippets/pdp-purchase-confidence.liquid)
    7.  Photos / details / care / full size chart (existing accordions)
    8.  Similar styles / recommendations
    9.  Reviews (kept low; above-fold review count suppressed via
        snippets/pdp-review-social-proof.liquid)

  Theme-editor block order can be tweaked per-product, but please keep
  the above as the canonical sequence — each step exists for a CRO
  reason documented in the corresponding snippet header.
{%- endcomment -%}
<section
  id="MainProduct-{{ section.id }}"
  class="section-{{ section.id }}-padding gradient color-{{ section.settings.color_scheme }}"
  data-section="{{ section.id }}"
>
  {%- liquid
    assign product_collection_handles = product.collections | map: 'handle' | join: '|'
    assign product_subcategory = product.metafields.custom.subcategory | default: blank
    assign product_subcategory_handle = product_subcategory | handleize
    assign product_title_downcase = product.title | downcase
    assign product_tags_downcase = product.tags | join: '|' | downcase
    assign mobile_gallery_ratio = product.featured_media.preview_image.aspect_ratio | default: product.featured_media.aspect_ratio | default: 1.0
    for product_media in product.media
      assign product_media_ratio = product_media.preview_image.aspect_ratio | default: product_media.aspect_ratio | default: blank
      if product_media_ratio != blank and product_media_ratio < mobile_gallery_ratio
        assign mobile_gallery_ratio = product_media_ratio
      endif
    endfor
    assign has_family_sets_context = false
    if product_collection_handles contains 'family-sets' or product_subcategory_handle == 'family-sets'
      assign has_family_sets_context = true
    endif
    assign has_matching_set_context = has_family_sets_context
    if product_collection_handles contains 'mommy-and-me' or product_collection_handles contains 'daddy-and-me' or product_collection_handles contains 'family-matching' or product_collection_handles contains 'matching-family' or product_collection_handles contains 'couples' or product_title_downcase contains 'mommy and me' or product_title_downcase contains 'daddy and me' or product_title_downcase contains 'family matching' or product_title_downcase contains 'matching set' or product_tags_downcase contains 'mommy-and-me' or product_tags_downcase contains 'daddy-and-me' or product_tags_downcase contains 'family-matching' or product_tags_downcase contains 'matching-family'
      assign has_matching_set_context = true
    endif
  -%}

  <div class="page-width page-width--product-breadcrumbs">
    {% render 'breadcrumbs' %}
  </div>

  {{ 'section-main-product.css' | asset_url | stylesheet_tag }}
  {{ 'component-accordion.css' | asset_url | stylesheet_tag }}
  {{ 'component-price.css' | asset_url | stylesheet_tag }}
  {{ 'component-card.css' | asset_url | stylesheet_tag }}
  {{ 'component-slider.css' | asset_url | stylesheet_tag }}
  {{ 'component-rating.css' | asset_url | stylesheet_tag }}
  {{ 'component-deferred-media.css' | asset_url | stylesheet_tag }}
  {{ 'component-product-desktop-ux-ruler-sync.css' | asset_url | stylesheet_tag }}
  {{ 'component-product-description.css' | asset_url | stylesheet_tag }}
  {% unless product.has_only_default_variant %}
    {{ 'component-product-variant-picker.css' | asset_url | stylesheet_tag }}
    {{ 'component-swatch-input.css' | asset_url | stylesheet_tag }}
    {{ 'component-swatch.css' | asset_url | stylesheet_tag }}
  {% endunless %}
  {%- if product.quantity_price_breaks_configured? -%}
    {{ 'component-volume-pricing.css' | asset_url | stylesheet_tag }}
  {%- endif -%}

  {%- style -%}
    .section-{{ section.id }}-padding {
      padding-top: {{ section.settings.padding_top | times: 0.75 | round: 0 }}px;
      padding-bottom: {{ section.settings.padding_bottom | times: 0.75 | round: 0 }}px;
    }

    @media screen and (min-width: 750px) {
      .section-{{ section.id }}-padding {
        padding-top: {{ section.settings.padding_top }}px;
        padding-bottom: {{ section.settings.padding_bottom }}px;
      }
    }

    /* Reserve PDP gallery height before deferred product CSS finishes loading. */
    #MainProduct-{{ section.id }} {
      --dlm-mobile-gallery-ratio: {{ mobile_gallery_ratio }};
    }

    #MainProduct-{{ section.id }} .product-media-container {
      aspect-ratio: var(--preview-ratio, 1);
    }

    #MainProduct-{{ section.id }} .product-media-container .media {
      display: block;
      position: relative;
      overflow: hidden;
      aspect-ratio: var(--preview-ratio, 1);
      padding-top: 0 !important;
    }

    #MainProduct-{{ section.id }} .product-media-container .media > img {
      display: block;
      position: absolute;
      inset: 0;
      width: 100%;
      height: 100%;
      max-width: 100%;
      object-fit: contain;
      object-position: center top;
    }

    #MainProduct-{{ section.id }} .scroll-trigger.animate--slide-in,
    #MainProduct-{{ section.id }} .scroll-trigger.animate--fade-in {
      animation: none !important;
      opacity: 1 !important;
      transform: none !important;
    }

    #MainProduct-{{ section.id }} .dlm-reference-ui .share-button {
      display: none !important;
      margin: 0 !important;
    }

    #MainProduct-{{ section.id }} .matching-size-guide__snapshot--reserved:empty {
      display: block !important;
      min-height: 24.3rem;
      visibility: hidden;
    }

